/**
 * Replays every case of the checked-in corpus (`__fixtures__/changesets.json`, generated by
 * `npm run collab:fixtures`) through the real @codemirror/state and asserts each recorded field.
 * A library upgrade that changes ChangeSet semantics fails here, which is what pins the Java port.
 */
import { describe, it, expect } from 'vitest';
import { ChangeSet, Text } from '@codemirror/state';
import fixture from './__fixtures__/changesets.json';

const EXPECTED_CASES = 1200;

describe('ChangeSet conformance corpus', () => {
  it('has the expected size and a representative mix', () => {
    expect(fixture.cases).toHaveLength(EXPECTED_CASES);
    const docs = fixture.cases.map((c) => c.doc);
    expect(docs.some((d) => /[\uD800-\uDBFF][\uDC00-\uDFFF]/.test(d))).toBe(true);
    expect(docs.some((d) => /[一-鿿]/.test(d))).toBe(true);
    expect(docs.some((d) => d === '')).toBe(true);
    expect(docs.some((d) => d.includes('\r\n'))).toBe(true);
  });

  it('records the library version that is installed', () => {
    expect(fixture.library).toMatch(/^@codemirror\/state \d+\.\d+\.\d+/);
  });

  it('every recorded field equals what the real library computes', () => {
    fixture.cases.forEach((c, i) => {
      const ctx = `case ${i}`;
      const a = ChangeSet.fromJSON(c.a);
      const b = ChangeSet.fromJSON(c.b);
      const cc = ChangeSet.fromJSON(c.c);
      const doc = Text.of(c.doc.split(/\r\n|\r|\n/));
      expect(a.length, ctx).toBe(doc.length);
      expect(b.length, ctx).toBe(doc.length);
      expect(a.apply(doc).toString(), ctx).toBe(c.applyA.split(/\r\n|\r|\n/).join('\n'));
      expect(a.compose(cc).toJSON(), ctx).toEqual(c.composeAC);
      expect(b.map(a).toJSON(), ctx).toEqual(c.mapBA);
      expect(b.map(a, true).toJSON(), ctx).toEqual(c.mapBABefore);
      for (const p of c.positions) {
        expect(a.mapPos(p.pos, -1), `${ctx} pos ${p.pos}`).toBe(p.left);
        expect(a.mapPos(p.pos, 1), `${ctx} pos ${p.pos}`).toBe(p.right);
      }
    });
  });
});
